sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSSRBXSN-3504 : SWB maker activity task not created
    // Once the status is updated to SWB extract Request Sent Successfully, validate if we have already received a response from SWB for the same QTrack ID

    var checkOutboundRec = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
    checkOutboundRec.addEncodedQuery('source=SMARTWORKBENCH^object_id=' + current.qtrack_id);
    checkOutboundRec.query();

    if (checkOutboundRec.next()) {
		//Checks for outbound record where event status as SWB_AUTOMATION_REVIEW_REQUIRED and current state of email case is either NEW or WORK IN PROGRESS
        if (checkOutboundRec.event_status == "SWB_AUTOMATION_REVIEW_REQUIRED" && (current.state == "1" || current.state == "2")) {
            current.swb_status = "SWB Review Required";
            current.state = '2';
			current.update();
        }

		//Checks for outbound record where event status as SWB_AUTOMATION_UNCATEGORIZED and current state of email case is either NEW or WORK IN PROGRESS
        if (checkOutboundRec.event_status == "SWB_AUTOMATION_UNCATEGORIZED" && (current.state == "1" || current.state == "2")) {
            current.swb_status = "SWB Email Uncategorized";
			current.update();
        }

		//Checks for outbound record where event status as SWB_INBOUND_MSG_FAILED or SWB_SERVICE_UNAVAILABLE or SWB_INDEXING_FAIL and current state of email case is either NEW or WORK IN PROGRESS
        if ((checkOutboundRec.event_status == "SWB_INBOUND_MSG_FAILED" || checkOutboundRec.event_status == "SWB_SERVICE_UNAVAILABLE" || checkOutboundRec.event_status == "SWB_INDEXING_FAIL") && (current.state == "1" || current.state == "2")) {
            current.swb_status = "SWB Service Unavailable or SWB Inbound Message Failed";
			current.update();
        }
    }


})(current, previous);
